// Key service functions in chat.js
const findConversation = async (teacherId, peerId) => {
  const convosRef = admin.firestore().collection('conversations');
  const query = convosRef.where('members', 'array-contains-any', [teacherId, peerId]);
  const snap = await query.get();
  return snap.docs.find(doc => doc.data().members.includes(teacherId) && doc.data().members.includes(peerId));
};

const createConversation = async (teacherId, peerId) => {
  const convosRef = admin.firestore().collection('conversations');
  const newConvo = await convosRef.add({
    members: [teacherId, peerId],
    unreadCounts: { [teacherId]: 0, [peerId]: 0 },
    lastUpdated: admin.firestore.FieldValue.serverTimestamp()
  });
  return newConvo;
};

